css:
.shi-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.shi-root,.shi-root *,.shi-root *::before,.shi-root *::after{box-sizing:border-box}
.shi-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.shi-root img{display:block;border:0;max-width:none}
.shi-root [hidden]{display:none!important}
.shi-root [data-sh-theme="light"]{display:none!important}
.shi-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.shi-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.shi-root .n67_1958{align-content:stretch;display:flex;gap:7px;align-items:flex-start;position:relative;flex-shrink:0}
.shi-root .n67_1959{height:5px;position:relative;flex-shrink:0;width:7px}
.shi-root .x15{position:absolute;inset:-28.48% -14.53%}
.shi-root .x16{display:block;max-width:none;width:100%;height:100%}
.shi-root .n67_1960{word-break:break-word;-webkit-background-clip:text;background-clip:text;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:19px;font-style:normal;position:relative;flex-shrink:0;font-size:16px;color:transparent;white-space:nowrap;background-image:linear-gradient(to bottom,var(--wa-point, #c2e9fb),var(--wa-point, #a1c4fd));width:133px}
.shi-root [data-node-id="68:2047"]{border-color:transparent!important}
.shi-root [data-node-id="68:2047"]::after{content:"";position:absolute;inset:0px;border-radius:inherit;padding:1px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(0deg,var(--wa-point, #5fadcc) 0%,var(--wa-point, #697eff) 100%)}
.shi-root [data-node-id="68:2137"]{border-color:transparent!important}
.shi-root [data-node-id="68:2137"]::after{content:"";position:absolute;inset:0px;border-radius:inherit;padding:1px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(0deg,var(--wa-point, #5fadcc) 0%,var(--wa-point, #697eff) 100%)}
.shi-root [data-node-id="68:2193"]{border-color:transparent!important}
.shi-root [data-node-id="68:2193"]::after{content:"";position:absolute;inset:0px;border-radius:inherit;padding:1px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;background:linear-gradient(0deg,var(--wa-point, #5fadcc) 0%,var(--wa-point, #697eff) 100%)}
.shi-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.shi-root[data-theme="light"] [data-name^="Screen/"] > [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.shi-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.shi-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.shi-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
